-- 2026-09-14 canonical60割当を維持し承認済み指数補間を接続。
-- 旧release/battle/fixture UUIDのgrowth割当を継承しない。
-- ownership/Lv/awakening/xp/資産/確定snapshotを変更しない。current projectionのみ再計算。
BEGIN;
SET LOCAL lock_timeout='3s'; SET LOCAL statement_timeout='45s';
CREATE TEMP TABLE growth_before (name text PRIMARY KEY, fingerprint text);
DO $audit$
DECLARE t text; h text;
BEGIN
 FOREACH t IN ARRAY ARRAY['ranking_seasons','ranking_pvp_season_snapshots','ranking_raid_personal_season_snapshots','ranking_raid_guild_season_snapshots','ranking_guild_power_season_snapshots','ranking_daily_activity_snapshots','ranking_daily_entity_snapshots','ranking_daily_recipient_snapshots','raid_room_combat_snapshots','gvg_match_member_snapshots','social_activity_feed','social_activity_projection_state','users','user_characters','user_items','battle_replay_sessions','battle_replay_events','canonical_character_master','character_battle_master','equipment_battle_master','skill_battle_master'] LOOP
 IF to_regclass('public.'||t) IS NOT NULL THEN
 EXECUTE format('SELECT md5(coalesce(string_agg(j,'''' ORDER BY j),'''')) FROM (SELECT to_jsonb(r)::text j FROM public.%I r) s',t) INTO h;
 INSERT INTO growth_before VALUES(t,h);
 END IF;
 END LOOP;
 INSERT INTO growth_before VALUES('trigger_states',(SELECT md5(string_agg(tgrelid::text||tgname||tgenabled::text,'' ORDER BY tgrelid,tgname)) FROM pg_trigger WHERE NOT tgisinternal));
END $audit$;

DO $guard$
BEGIN
 IF md5(pg_get_functiondef('public.canonical_character_stats(text,integer,integer)'::regprocedure))
 <> '2c196719fe8fcd72b10ffc2c5e578d7e' THEN RAISE EXCEPTION 'CANONICAL_GROWTH_RUNTIME_SOURCE_DRIFT'; END IF;
END $guard$;
CREATE TABLE public.canonical_character_growth_exponents (
 growth_pattern_id text PRIMARY KEY,
 hp numeric NOT NULL CHECK(hp>0),atk numeric NOT NULL CHECK(atk>0),
 def numeric NOT NULL CHECK(def>0),spd numeric NOT NULL CHECK(spd>0),luk numeric NOT NULL CHECK(luk>0)
);
