_id":"char_tomoya_01","def":8676,"growth_pattern":"BALANCED","hp":89343,"level":50,"luk":32,"spd":406},{"atk":15242,"awakening":5,"character_id":"char_tomoya_01","def":15183,"growth_pattern":"BALANCED","hp":156350,"level":50,"luk":38,"spd":487},{"atk":16700,"awakening":0,"character_id":"char_tomoya_01","def":16600,"growth_pattern":"BALANCED","hp":170000,"level":100,"luk":56,"spd":740},{"atk":29225,"awakening":5,"character_id":"char_tomoya_01","def":29050,"growth_pattern":"BALANCED","hp":297500,"level":100,"luk":67,"spd":888}]$expected$::jsonb) AS t(character_id text,level integer,awakening integer,growth_pattern text,hp integer,atk integer,def integer,spd integer,luk integer);
DO $test$
BEGIN
 IF EXISTS(SELECT 1 FROM growth_client_expected e CROSS JOIN LATERAL public.canonical_character_stats(e.character_id,e.level,e.awakening) s WHERE (e.hp,e.atk,e.def,e.spd,e.luk) IS DISTINCT FROM (s.hp,s.atk,s.def,s.spd,s.luk))
 THEN RAISE EXCEPTION 'CLIENT_SERVER_GROWTH_PARITY_FAILED'; END IF;
 IF (SELECT count(*) FROM growth_client_expected e CROSS JOIN LATERAL public.canonical_character_stats(e.character_id,e.level,e.awakening))<>360 THEN RAISE EXCEPTION 'MISSING_CANONICAL_CHARACTER'; END IF;
END $test$;
DO $audit$
DECLARE r record; h text;
BEGIN
 FOR r IN SELECT * FROM growth_before WHERE name<>'trigger_states' LOOP
 EXECUTE format('SELECT md5(coalesce(string_agg(j,'''' ORDER BY j),'''')) FROM (SELECT to_jsonb(r)::text j FROM public.%I r) s',r.name) INTO h;
 IF h IS DISTINCT FROM r.fingerprint THEN RAISE EXCEPTION 'PROTECTED_DATA_CHANGED: %',r.name; END IF;
 END LOOP;
 IF (SELECT fingerprint FROM growth_before WHERE name='trigger_states')
 IS DISTINCT FROM (SELECT md5(string_agg(tgrelid::text||tgname||tgenabled::text,'' ORDER BY tgrelid,tgname)) FROM pg_trigger WHERE NOT tgisinternal)
 THEN RAISE EXCEPTION 'TRIGGER_STATE_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM public.users u LEFT JOIN public.user_power_rankings p ON p.user_id=u.id WHERE p.total_power IS DISTINCT FROM least(public.calculate_user_total_power(u.id),2147483647)::integer)
 THEN RAISE EXCEPTION 'CURRENT_POWER_PROJECTION_MISMATCH'; END IF;
END $audit$;
SELECT jsonb_build_object('client_server_cases',360,'canonical_assignments',(SELECT count(*) FROM canonical_character_growth_assignments),'protected_table_hashes',(SELECT count(*)-1 FROM growth_before),'trigger_state_unchanged',true,'current_power_projection_consistent',true) result;
ROLLBACK;
